function cPartColor(v){return v<30?'#ff6945':v<60?'#edc271':'#74dcc2';}function drawRadar(){const ctx=$('radar').getContext('2d'),p=world.cars[0];ctx.clearRect(0,0,160,160);ctx.fillStyle='#10203099';ctx.strokeStyle='#9badbd66';ctx.lineWidth=2;ctx.beginPath();ctx.arc(80,80,74,0,Math.PI*2);ctx.fill();ctx.stroke();for(const c of world.cars){const x=80+c.x/RADIUS*69,y=80+c.z/RADIUS*69;ctx.fillStyle=c.dead?'#5c6570':c.id===0?'#ff9263':'#dce4e9';ctx.beginPath();ctx.arc(x,y,c.id===0?4:2.4,0,Math.PI*2);ctx.fill();if(c.id===0){ctx.strokeStyle='#ff9263';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+Math.sin(p.heading)*10,y+Math.cos(p.heading)*10);ctx.stroke();}}}
